// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public { c = new PrivateBank(address(this)); }

    function testFuzz_property(address depositor, address other, uint128 amt) public {
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));

        uint256 value = uint256(amt) % 1 ether;

        vm.deal(depositor, 1 ether);

        uint256 beforeOther = c.balances(other);

        vm.prank(depositor);
        c.Deposit{value: value}();

        uint256 afterOther = c.balances(other);

        assertTrue(afterOther == beforeOther);
    }
}
